 const orderedPets=[...state.mascotas].sort((a,b)=>{const order=['mally','arisu','lucy'];const ai=order.indexOf(String(a.nombre||'').trim().toLowerCase()),bi=order.indexOf(String(b.nombre||'').trim().toLowerCase());return (ai<0?99:ai)-(bi<0?99:bi)});
 const petCards=orderedPets.map((p,i)=>{const items=allCare.filter(x=>x.pet===p.id);const late=items.filter(x=>x.when<date());const next=items.find(x=>x.when>=date());const img=p.foto?'<img class="home-pet-avatar" src="'+escape(p.foto)+'" alt="Foto de '+escape(p.nombre)+'">':'<div class="home-pet-avatar home-pet-placeholder">'+(String(p.especie||'').toLowerCase().includes('perr')?'🐶':'🐱')+'</div>';return '<article class="home-pet-card home-pet-tone-'+(i%3)+'"><div class="home-pet-top">'+img+'<div><h3>'+escape(p.nombre)+'</h3><small>'+escape(p.especie||'Mascota')+'</small></div></div><p>'+(late.length?'🔴 '+late.length+' cuidado(s) atrasado(s)':next?'📅 Próximo: '+escape(displayDate(next.when))+' · '+escape(next.nombre||sections[next.kind]):'💚 Sin cuidados próximos registrados')+'</p><div class="home-pet-actions"><button data-page="mascotas">Ver perfil</button><button data-page="vacunas">💉 Vacunas</button></div></article>'}).join('');
